static oled_animation_state_t luna_anim_state;
static bool                   luna_initialized = false;

void animate_luna(uint8_t luna_x, uint8_t luna_y) {
    if (!luna_initialized) {
        oled_animation_init(&luna_anim_state, LUNA_ANIM_FRAMES, LUNA_ANIM_FRAME_DURATION);
        luna_initialized = true;
    }

    oled_set_cursor(luna_x, luna_y);
    uint8_t current_frame = oled_animation_update(&luna_anim_state);

    if (is_caps_word_on()) {
        oled_write_raw_P(luna_barks[current_frame], LUNA_ANIM_SIZE);
    } else if (last_input_activity_elapsed() > LUNA_RUN_TO_SIT_IDLE_TIME_MS) {
        oled_write_raw_P(luna_sits[current_frame], LUNA_ANIM_SIZE);
    } else {
        oled_write_raw_P(luna_runs[current_frame], LUNA_ANIM_SIZE);
    }
}

void render_luna(uint8_t luna_x, uint8_t luna_y) {
    animate_luna(luna_x, luna_y);
}
